-- 2. Справочник объектов (objects(ОбъектыCSV).csv)
DROP TABLE IF EXISTS ml.ref_objects CASCADE;
CREATE TABLE ml.ref_objects (
    "ид_объект"                       bigint PRIMARY KEY,
    "иерархия_уровень"                integer,
    "родитель"                        bigint,
    "вид_объекта"                     text,
    "диспетчерское_название_объекта"  text
);

-- 3. ИСПРАВЛЕННЫЙ справочник состояний.
-- В исходном state_collector.csv колонка тип_датчика сдвинута относительно наборов
-- (напр. «Обнаружен газ» подписано как «Датчик температуры», «На охране» - как «Состояние насоса»).
-- Здесь пары (тип_датчика, состояние) взяты из фактического журнала (все 162 пары, встречающиеся
-- у каналов из справочника), а флаг тревожности - из state_collector по названию состояния:
--   * суффикс «1» («Температура ниже 3ºC1») убран;
--   * «Температура ниже 3ºC» помечена и true, и false -> принято TRUE;
--   * «Обесточен»: для «Состояние фазы» FALSE (набор 10 «Есть питание/Обесточен»), для остальных TRUE (наборы 8, 9).
-- доля_тревожных_в_журнале - доля строк с тревожное_raw='t' для справки/контроля.
DROP TABLE IF EXISTS ml.ref_state_fixed CASCADE;
CREATE TABLE ml.ref_state_fixed (
    "тип_датчика"               text    NOT NULL,
    "название_состояния"        text    NOT NULL,
    "тревожное"                 boolean NOT NULL,
    "флаг_в_исходном_справочнике" text,
    "строк_в_журнале"           bigint,
    "доля_тревожных_в_журнале"  numeric(6,3),
    PRIMARY KEY ("тип_датчика","название_состояния")
);

COMMIT;

-- Контроль: ожидается 11485 / 95 / 162
SELECT (SELECT count(*) FROM ml.ref_channels) AS каналов,
       (SELECT count(*) FROM ml.ref_objects)  AS объектов,
       (SELECT count(*) FROM ml.ref_state_fixed) AS пар_состояний;
